import re
import datetime

wiki_path = '/home/zhouhuijuan1987/wiki/youtube-video-research-wiki'

def extract_frontmatter(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    # extract frontmatter between --- lines
    match = re.search(r'^---\n(.*?)\n---', content, re.DOTALL | re.MULTILINE)
    if match:
        fm = match.group(1)
        data = {}
        for line in fm.split('\n'):
            if ':' in line:
                key, val = line.split(':', 1)
                data[key.strip()] = val.strip()
        return data
    return {}

def get_summary(filepath):
    fm = extract_frontmatter(filepath)
    return fm.get('summary', '')

def get_title(filepath):
    fm = extract_frontmatter(filepath)
    return fm.get('title', '')

def collect_files_by_type():
    types = {
        'sources': [],
        'entities': [],
        'concepts': [],
        'comparisons': [],
        'overview': [],
        'queries': []
    }
    for root, dirs, files in os.walk(os.path.join(wiki_path, 'wiki')):
        for f in files:
            if f.endswith('.md'):
                full = os.path.join(root, f)
                rel = os.path.relpath(full, os.path.join(wiki_path, 'wiki'))
                # Determine type from directory
                if rel.startswith('sources/'):
                    types['sources'].append((full, rel))
                elif rel.startswith('entities/'):
                    types['entities'].append((full, rel))
                elif rel.startswith('concepts/'):
                    types['concepts'].append((full, rel))
                elif rel.startswith('comparisons/'):
                    types['comparisons'].append((full, rel))
                elif rel.startswith('overview/'):
                    types['overview'].append((full, rel))
                elif rel.startswith('queries/'):
                    types['queries'].append((full, rel))
                elif full.endswith('index.md') or full.endswith('log.md'):
                    pass
    return types

def sort_by_title(items):
    # items: list of (fullpath, relpath)
    def get_title_key(item):
        fm = extract_frontmatter(item[0])
        return fm.get('title', '').lower()
    return sorted(items, key=get_title_key)

types = collect_files_by_type()
for k in types:
    types[k] = sort_by_title(types[k])

# Generate index content
lines = []
